<template><div class="cpw-overlay" @click.self="$emit('close')"><div class="cpw-modal"><button class="cpw-close" @click="$emit('close')">&times;</button><h2>{{user?.email?t('updateEmail'):t('bindEmail')}}</h2><form class="cpw-form" @submit.prevent="submit"><div class="cpw-field"><label>{{t('emailLabel')}}</label><input v-model="email" type="email" :placeholder="t('emailPlaceholder')" required></div><div v-if="!sent" class="cpw-field"><label>{{t('passwordLabel')}}</label><input v-model="password" type="password" :placeholder="t('bindEmailPasswordPlaceholder')" required></div><div v-if="sent" class="cpw-field"><label>{{t('emailVerificationCode')}}</label><input v-model="code" maxlength="6" :placeholder="t('emailCodePlaceholder')" required></div><div v-if="error" class="cpw-error">{{error}}</div><div v-if="success" class="cpw-success">{{success}}</div><button class="cpw-submit" :disabled="loading">{{loading?t('submitting'):(sent?t('confirmBindEmail'):t('sendVerificationCode'))}}</button></form></div></div></template><script setup>import {ref} from 'vue';import {useAuth,useLang} from '../contexts/app';import {authService} from '../services/authService';import './ChangePasswordModal.css';const emit=defineEmits(['close']);const {user,updateUser}=useAuth();const {t}=useLang();const email=ref(user.value?.email||''),password=ref(''),code=ref(''),sent=ref(false),error=ref(''),success=ref(''),loading=ref(false);const submit=async()=>{error.value='';success.value='';loading.value=true;try{if(!sent.value){const d=await authService.sendBindEmailCode(email.value,password.value);sent.value=true;password.value='';success.value=d.detail||t('emailCodeSent')}else{updateUser(await authService.confirmEmail(email.value,code.value));success.value=t('emailBindSuccess');setTimeout(()=>emit('close'),1200)}}catch(e){error.value=e.response?.data?.detail||t('emailBindFailed')}finally{loading.value=false}};</script>
